import { createRoot } from "react-dom/client";
import { FindField } from "../../../tools/workbench/src/main/frontend/graph-explorer/find-field.tsx";

function Harness() {
  const inputRef = useRef<HTMLInputElement>(null);
  const [size, setSize] = useState<number | null>(100001);
  const [busy, setBusy] = useState(false);
  const [calls, setCalls] = useState<string[]>([]);
  return <>
    <button onClick={() => setSize(100000)}>Small</button>
    <button onClick={() => setSize(100001)}>Large</button>
    <button onClick={() => setSize(null)}>Unknown</button>
    <button onClick={() => setBusy(!busy)}>Toggle busy</button>
    <FindField nodes={[{id:"urn:alice",label:"Alice",kind:"iri"}]} busy={busy} inputRef={inputRef}
      repositorySize={size} onReveal={id => setCalls(c => [...c, `reveal:${id}`])}
      onSearchRepository={term => setCalls(c => [...c, `search:${term}`])} />
    <output>{JSON.stringify(calls)}</output>
  </>;
}
createRoot(document.getElementById("root")!).render(<Harness />);
